local HopperScaleMaker = {}
local PRODUCTS = {
    iron_hopperscale = { name = "Železni tehtnica za lijake", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni tehtnica za lijake za mlinarje." },
    bronze_hopperscale = { name = "Bronast tehtnica za lijake", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast tehtnica za lijake za mlinarje." },
    silver_hopperscale = { name = "Srebrn tehtnica za lijake", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn tehtnica za lijake za mlinarje." },
    gilded_hopperscale = { name = "Pozlačen tehtnica za lijake", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen tehtnica za lijake za mlinarje." },
    jewel_set_hopperscale = { name = "Draguljast tehtnica za lijake", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast tehtnica za lijake za mlinarje." },
    royal_sovereign_hopperscale = { name = "Kraljevski suveren tehtnica za lijake", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren tehtnica za lijake z biseri za krono." },
}
local BUILDINGS = {
    hopperscale_workshop = { name = "Hopperscale delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hopperscale_house = { name = "Hopperscale hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hopperscale_atelier = { name = "Mojstrski hopperscale atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_hopperscale_palace = { name = "Suverena hopperscale palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HopperScaleMaker.ironStock = 16; HopperScaleMaker.bronzeStock = 14; HopperScaleMaker.woodStock = 10; HopperScaleMaker.leatherStock = 8; HopperScaleMaker.silverStock = 8; HopperScaleMaker.goldStock = 6; HopperScaleMaker.jewelStock = 4; HopperScaleMaker.pearlStock = 4
HopperScaleMaker.productStock = {}; HopperScaleMaker.buildings = {}; HopperScaleMaker.maker = nil; HopperScaleMaker.activeMaking = {}; HopperScaleMaker.totalProducts = 0; HopperScaleMaker.dayTimer = 0
function HopperScaleMaker.init() HopperScaleMaker.ironStock=16; HopperScaleMaker.bronzeStock=14; HopperScaleMaker.woodStock=10; HopperScaleMaker.leatherStock=8; HopperScaleMaker.silverStock=8; HopperScaleMaker.goldStock=6; HopperScaleMaker.jewelStock=4; HopperScaleMaker.pearlStock=4; HopperScaleMaker.productStock={}; HopperScaleMaker.buildings={}; HopperScaleMaker.maker=nil; HopperScaleMaker.activeMaking={}; HopperScaleMaker.totalProducts=0; HopperScaleMaker.dayTimer=0; print("[HopperScaleMaker] Royal Hopper Scale Maker System initialized (6 products, 4 buildings)") end
function HopperScaleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HopperScaleMaker.maker={name=n or ("Tehtar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtar najet: %s (spretnost: %d)",HopperScaleMaker.maker.name,s),"success") end; return true end
function HopperScaleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HopperScaleMaker.build(id) local ok,e=HopperScaleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HopperScaleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HopperScaleMaker.getQualityBonus() local b=0; for _,bd in ipairs(HopperScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HopperScaleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HopperScaleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HopperScaleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HopperScaleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HopperScaleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HopperScaleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HopperScaleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HopperScaleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HopperScaleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HopperScaleMaker.buildings==0 then return false,"Potrebna tehtalna delavnica" end; if not HopperScaleMaker.maker then return false,"Potreben tehtar" end; return true end
function HopperScaleMaker.make(pt,qty) qty=qty or 1; local ok,e=HopperScaleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HopperScaleMaker.ironStock=HopperScaleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HopperScaleMaker.bronzeStock=HopperScaleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HopperScaleMaker.woodStock=HopperScaleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HopperScaleMaker.leatherStock=HopperScaleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HopperScaleMaker.silverStock=HopperScaleMaker.silverStock-d.silverCost*qty end; if d.goldCost then HopperScaleMaker.goldStock=HopperScaleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HopperScaleMaker.jewelStock=HopperScaleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HopperScaleMaker.pearlStock=HopperScaleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HopperScaleMaker.maker then t=math.max(1,t-math.floor(HopperScaleMaker.maker.skill/13)) end; table.insert(HopperScaleMaker.activeMaking,{id="hopperscale_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HopperScaleMaker.completeMaking(m) local q=1.0+(HopperScaleMaker.getQualityBonus()/100); if HopperScaleMaker.maker then q=q+(HopperScaleMaker.maker.skill/140) end; q=math.min(2.5,q); HopperScaleMaker.productStock[m.productType]=(HopperScaleMaker.productStock[m.productType] or 0)+m.quantity; HopperScaleMaker.totalProducts=HopperScaleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HopperScaleMaker.maker then HopperScaleMaker.maker.itemsMade=HopperScaleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HopperScaleMaker.maker.skill=math.min(100,HopperScaleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hopperscale.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HopperScaleMaker.update(dt) if not _G.state then return end; HopperScaleMaker.dayTimer=HopperScaleMaker.dayTimer+dt; if HopperScaleMaker.dayTimer>=30 then HopperScaleMaker.dayTimer=0; for i=#HopperScaleMaker.activeMaking,1,-1 do local m=HopperScaleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HopperScaleMaker.completeMaking(m); table.remove(HopperScaleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HopperScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HopperScaleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HopperScaleMaker.getStats() return {ironStock=HopperScaleMaker.ironStock,bronzeStock=HopperScaleMaker.bronzeStock,woodStock=HopperScaleMaker.woodStock,leatherStock=HopperScaleMaker.leatherStock,silverStock=HopperScaleMaker.silverStock,goldStock=HopperScaleMaker.goldStock,jewelStock=HopperScaleMaker.jewelStock,pearlStock=HopperScaleMaker.pearlStock,productStock=HopperScaleMaker.productStock,numBuildings=#HopperScaleMaker.buildings,hasMaker=HopperScaleMaker.maker~=nil,makerName=HopperScaleMaker.maker and HopperScaleMaker.maker.name or "—",makerSkill=HopperScaleMaker.maker and HopperScaleMaker.maker.skill or 0,activeMaking=#HopperScaleMaker.activeMaking,totalProducts=HopperScaleMaker.totalProducts} end
return HopperScaleMaker
